<template><div class="page"><PageState v-if="query.isLoading.value" type="loading" :title="`正在加载 ${kindName} 集群`"/><PageState v-else-if="!component" type="error" :title="`未找到 ${kindName} 集群`" description="该集群不存在，或类型与访问路径不一致。"/><template v-else><section class="hero"><div><button class="hero-path" @click="back">{{kindName}} 集群 / 集群列表 /</button><div class="hero-title"><h1>{{component.name}}</h1><StatusBadge :value="component.status??component.deployStatus"/><t-tag class="source-tag" variant="outline">{{liveComponent?'LIVE + MOCK':'MOCK DATA'}}</t-tag></div><p>{{component.description}}</p><div class="hero-meta"><span>{{kindName}} {{component.version}}</span><span>{{component.region}}</span><span>{{nodes.length}} {{kind==='runtime'?'Instances':'Nodes'}}</span></div></div><div class="hero-actions"><t-button variant="outline" :loading="query.isFetching.value" @click="query.refetch()"><RefreshIcon/>刷新</t-button><t-button theme="primary" @click="openTopology"><TreeRoundDotIcon/>查看拓扑</t-button></div></section><nav class="tabs"><button v-for="item in config.panels" :key="item" :class="{active:item===panel}" @click="openPanel(item)">{{config.panelLabels[item]}}</button></nav>
  <template v-if="panel==='overview'"><MetricStrip :items="metrics"/><div class="overview-grid"><section class="panel"><div class="section-heading"><div><h2>{{kind==='runtime'?'消息处理趋势':'注册与发现趋势'}} · Mock</h2><p>后端暂无稳定时序接口</p></div><t-tag variant="outline">ANTV G2</t-tag></div><TrendChart :input="trendInput"/></section><section class="panel summary-card"><h2>集群信息</h2><p>{{kindName}} 集群的部署与关联信息</p><dl class="fact-list"><div><dt>集群类型</dt><dd>{{kindName}}</dd></div><div><dt>版本</dt><dd>{{component.version}}</dd></div><div><dt>地域</dt><dd>{{component.region}}</dd></div><div><dt>{{kind==='meta'?'主动关联 EventMesh':'关联 EventMesh'}}</dt><dd>{{componentRelations.length}}</dd></div></dl></section></div><section class="panel"><div class="section-heading"><div><h2>运行状态</h2><p>部署状态与模拟可观测信息明确分离</p></div></div><div class="health-grid"><div><StatusBadge value="healthy" label="节点可用性"/><strong>{{healthyNodes}} / {{nodes.length}}</strong></div><div><StatusBadge value="healthy" :label="kind==='runtime'?'路由状态':'注册状态'"/><strong>正常 · Mock</strong></div><div><StatusBadge value="unknown" label="健康探测"/><strong>未接入</strong></div></div></section></template>
  <DataPanel v-else-if="panel==='instances'||panel==='nodes'" :title="kind==='runtime'?'Runtime 实例':'Meta 节点'" description="节点生命周期和地址信息" :data="nodes" :columns="nodeColumns"><template #toolbar><t-button theme="primary" @click="nodeVisible=true">添加节点 · Mock</t-button></template><template #name="{row}"><span class="identity-cell"><ServerIcon/><span><strong>{{row.name}}</strong><small>{{row.id}}</small></span></span></template><template #status="{row}"><StatusBadge :value="row.status??row.deployStatus" :code="row.deployStatus"/></template></DataPanel>
  <DataPanel v-else-if="panel==='connections'" title="客户端连接" description="Runtime 客户端连接（前端模拟，后端尚无稳定端点）" :data="connections" :columns="connectionColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template></DataPanel>
  <DataPanel v-else-if="panel==='topics'" title="EventMesh Topics / Subscriptions" description="Runtime 侧业务 Topic 与订阅摘要" :data="topics" :columns="topicColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template></DataPanel>
  <DataPanel v-else-if="panel==='registry'" title="Runtime 注册信息" description="Meta 注册表与发现信息；缺失指标标记为 Mock" :data="registry" :columns="registryColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template></DataPanel>
  <DataPanel v-else title="关联 EventMesh" :description="kind==='meta'?'Meta 集群主动关联 EventMesh':'引用当前 Runtime 集群的 EventMesh'" :data="relationRows" :columns="relationColumns"><template #toolbar><t-button v-if="kind==='meta'" theme="primary" @click="relationVisible=true">建立主动关联 · Mock</t-button></template><template #status="{row}"><StatusBadge :value="row.status"/></template><template #actions="{row}"><t-button variant="text" @click="router.push(`/clusters/${row.id}/topology`)">查看拓扑</t-button><t-button v-if="kind==='meta'&&row.mock" variant="text" theme="danger" @click="detach(row)">解除</t-button></template></DataPanel>
  <t-dialog v-model:visible="nodeVisible" header="添加节点 · Mock" @confirm="addNode"><div class="dialog-form"><div class="dialog-note">名称使用 codex-sim- 前缀，仅保存在浏览器。</div><label>节点名称<t-input v-model="nodeName"/></label></div></t-dialog>
  <t-dialog v-model:visible="relationVisible" header="Meta 主动关联 EventMesh · Mock" @confirm="attach"><div class="relation-grid"><label v-for="item in availableEventMeshes" :key="item.id" class="relation-option"><t-checkbox v-model="selectedIds" :value="item.id"/><span><strong>{{item.name}}</strong><br><small>{{item.region}}</small></span></label></div></t-dialog>
  </template></div></template>
<script setup lang="ts">
import { computed, ref } from "vue";import { useRoute,useRouter } from "vue-router";import { useQuery } from "@tanstack/vue-query";import { MessagePlugin } from "tdesign-vue-next";import { RefreshIcon,ServerIcon,TreeRoundDotIcon } from "tdesign-icons-vue-next";import { dashboardRepository } from "../api/dashboardRepository";import { COMPONENT_DEFINITIONS,isComponentPanel } from "../config/clusterDefinitions";import { mockComponentClusters } from "../mock/mockClusterRelations";import { mockClusters,mockMessageSeries } from "../mock/mockClusterData";import { ensureSimName } from "../mock/mockWritableResources";import { useMockClusterStore } from "../stores/mockCluster";import MetricStrip from "../components/common/MetricStrip.vue";import StatusBadge from "../components/common/StatusBadge.vue";import PageState from "../components/common/PageState.vue";import DataPanel from "../components/common/DataPanel.vue";import TrendChart from "../components/charts/TrendChart.vue";
const route=useRoute(),router=useRouter(),store=useMockClusterStore();const clusterId=computed(()=>String(route.params.clusterId)),componentId=computed(()=>String(route.params.componentClusterId)),kind=computed(()=>route.params.componentType==="meta"?"meta":"runtime"),kindName=computed(()=>kind.value==="meta"?"Meta":"Runtime"),config=computed(()=>COMPONENT_DEFINITIONS[kind.value]),panel=computed(()=>isComponentPanel(kind.value,route.params.panel)?String(route.params.panel):"overview");
const query=useQuery({queryKey:computed(()=>["component-console",clusterId.value,kind.value,componentId.value]),queryFn:async()=>{if(kind.value==="meta"){const result=await dashboardRepository.getMetaClusterList(clusterId.value);return result.data.clusters.find((x:any)=>x.id===componentId.value||x.name===componentId.value)??null}return null},enabled:computed(()=>kind.value==="meta"),retry:false});const liveComponent=computed(()=>query.data.value);const base=computed(()=>liveComponent.value??mockComponentClusters.find((x:any)=>x.id===componentId.value&&x.type===kind.value));const component=computed(()=>base.value?{...base.value,status:base.value.status??base.value.deployStatus}:null);const nodes=computed(()=>[...(component.value?.nodes??[]),...store.resources.nodes.filter((x:any)=>x.clusterId===componentId.value)]);const componentRelations=computed(()=>store.relations.filter((x:any)=>x.componentClusterId===componentId.value));const healthyNodes=computed(()=>nodes.value.filter((x:any)=>/healthy|success|正常/i.test(String(x.status??x.deployStatus))).length);const metrics=computed(()=>[{label:kind.value==="runtime"?"Runtime 实例":"Meta 节点",value:nodes.value.length,note:"Live + Mock"},{label:"部署正常",value:healthyNodes.value,note:"按状态汇总"},{label:kind.value==="meta"?"主动关联":"反向引用",value:componentRelations.value.length,note:"EventMesh"},{label:kind.value==="runtime"?"客户端":"注册记录",value:nodes.value.length,note:"Mock"},{label:"健康探测",value:"—",note:"未接入"}]);const trendInput=computed(()=>({points:mockMessageSeries.labels.flatMap((time:string,i:number)=>[{time,series:kind.value==="runtime"?"流入":"注册",value:mockMessageSeries.inbound[i]},{time,series:kind.value==="runtime"?"流出":"发现",value:mockMessageSeries.outbound[i]}]),unit:kind.value==="runtime"?"K/s":"次/s",source:"mock" as const,status:"ready" as const}));
const nodeColumns=[{colKey:"name",title:"节点"},{colKey:"role",title:"角色"},{colKey:"address",title:"地址"},{colKey:"cpu",title:"CPU"},{colKey:"memory",title:"内存"},{colKey:"status",title:"状态"}];const connections=computed(()=>nodes.value.map((x:any,i:number)=>({id:i,name:`client-${i+1}`,protocol:["HTTP","TCP","MQTT"][i%3],runtime:x.name,count:"—",status:x.status??"unknown"})));const connectionColumns=[{colKey:"name",title:"客户端"},{colKey:"protocol",title:"协议"},{colKey:"runtime",title:"Runtime"},{colKey:"count",title:"连接数"},{colKey:"status",title:"状态"}];const topics=computed(()=>store.resources.topics.filter((x:any)=>x.eventMeshClusterId===clusterId.value).map((x:any)=>({...x,subscribers:"—",status:x.status??"healthy"})));const topicColumns=[{colKey:"name",title:"Topic"},{colKey:"partitions",title:"分区"},{colKey:"subscribers",title:"订阅"},{colKey:"status",title:"状态"}];const registry=computed(()=>nodes.value.map((x:any)=>({...x,clusterName:component.value?.name,type:"EVENTMESH_RUNTIME",ttl:"30 秒"})));const registryColumns=[{colKey:"name",title:"Runtime"},{colKey:"clusterName",title:"集群"},{colKey:"address",title:"地址"},{colKey:"type",title:"类型"},{colKey:"ttl",title:"租约"},{colKey:"status",title:"状态"}];const relationRows=computed(()=>componentRelations.value.map((rel:any)=>{const item=mockClusters.find((x:any)=>x.id===rel.eventMeshClusterId);return{id:rel.eventMeshClusterId,name:item?.name??rel.eventMeshClusterId,direction:kind.value==="meta"?"Meta → EventMesh":"EventMesh → Runtime",status:"healthy",createdAt:rel.createdAt,mock:true,relationId:rel.id}}));const relationColumns=[{colKey:"name",title:"EventMesh"},{colKey:"direction",title:"关系方向"},{colKey:"status",title:"状态"},{colKey:"createdAt",title:"建立时间"},{colKey:"actions",title:"操作"}];
function back(){router.push({path:`/clusters/${clusterId.value}/${kind.value}`,query:{section:"clusters"}})}function openPanel(next:string){router.push(`/clusters/${clusterId.value}/${kind.value}/${componentId.value}/${next}`)}function openTopology(){router.push({path:`/clusters/${clusterId.value}/topology`,query:{node:`component-${componentId.value}`}})}const nodeVisible=ref(false),nodeName=ref(`codex-sim-${kind.value}-new-01`);function addNode(){const name=ensureSimName(nodeName.value,`codex-sim-${kind.value}-new-01`);store.addNode({id:name,clusterId:componentId.value,name,role:kindName.value,address:"待分配",status:"unknown"});nodeVisible.value=false;MessagePlugin.success("节点已添加")};const relationVisible=ref(false),selectedIds=ref<string[]>([]);const availableEventMeshes=computed(()=>mockClusters.filter((x:any)=>!componentRelations.value.some((r:any)=>r.eventMeshClusterId===x.id)));function attach(){selectedIds.value.forEach((id:string)=>store.addRelations(id,[componentId.value],"meta"));selectedIds.value=[];relationVisible.value=false}function detach(row:any){store.removeRelation(row.relationId)}
</script>
<style scoped>.health-grid{display:grid;grid-template-columns:repeat(3,1fr)}.health-grid>div{min-height:95px;padding:18px;border-right:1px solid #e1e9f1;display:grid;gap:12px}.health-grid strong{font-size:18px}</style>
